from pybricks.parameters import Stop
from pybricks.tools import wait

from Team_Phoenix_Library import (
    phoenix_gyro_spin_turn_the_old_way,
    phoenix_gyro_straight,
    phoenix_gyro_turn,
)

# Set up.
cecmfe = 0

def run_white_mission(drive_base, left_drive, right_drive, left_attachment, right_attachment2, bottomsensor, cecmfe_):
    global cecmfe
    drive_base.use_gyro(True)
    right_attachment2.run_angle(50, 75)
    phoenix_gyro_straight(240, 450, 0, 1, drive_base, left_drive, right_drive)
    wait(150)
    phoenix_gyro_turn(100, 38, 30, 39, 'right', drive_base)
    wait(100)
    cecmfe = 48 - drive_base.angle()
    phoenix_gyro_straight(500, 450, cecmfe, 0.5, drive_base, left_drive, right_drive)
    phoenix_gyro_spin_turn_the_old_way(100, -38, 45, -45, 'left', drive_base, left_drive, right_drive)
    wait(50)
    cecmfe = -41 - drive_base.angle()
    phoenix_gyro_straight(55, 125, cecmfe, 0.5, drive_base, left_drive, right_drive)
    right_attachment2.run_angle(500, 1350)
    drive_base.drive(100, 0)
    while not bottomsensor.reflection() >= 87:
        wait(0)
    drive_base.brake()
    drive_base.settings(straight_speed=75)
    drive_base.straight(-35)
    right_attachment2.run_angle(500, 1740)
    drive_base.drive(100, 0)
    wait(600)
    drive_base.brake()
    drive_base.drive(-100, 0)
    wait(600)
    drive_base.brake()
    drive_base.drive(100, 0)
    wait(600)
    drive_base.brake()
    drive_base.drive(-100, 0)
    wait(600)
    drive_base.brake()
    drive_base.straight(-135)
    phoenix_gyro_spin_turn_the_old_way(125, -123, 45, -130, 'left', drive_base, left_drive, right_drive)
    wait(50)
    print(drive_base.angle())
    cecmfe = -130 - drive_base.angle()
    left_attachment.run_angle(500, 400)
    drive_base.straight(-100)
    left_attachment.run_angle(50, -200)
    drive_base.settings(straight_speed=600)
    drive_base.straight(600)
    print(drive_base.angle())


